files.after:
.ui_themePreview {
  display: block;
}

.ui_themePreview > .ant-tree .ant-tree-node-content-wrapper {
  color: var(--theme-preview-tree-color, #334155);
  padding: var(--theme-preview-tree-node-padding, 8px 12px);
  border-radius: var(--theme-preview-tree-node-radius, 6px);
}

.ui_themePreview > .ant-tree .ant-tree-node-content-wrapper:hover {
  background: var(--theme-preview-tree-color, #334155);
  padding: var(--theme-preview-tree-node-padding, 8px 12px);
  border-radius: var(--theme-preview-tree-node-radius, 6px);
}
